window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"letters","number":47,"source":"نامه 47.docx","mode":"explicit-parts","parts":["نامه 47\nبخش اول\nمتن:\nو من وصية له (علیه السلام) للحسن و الحسين (علیهما السلام) لما ضربَه ابنُ ملجم لعنه الله:\nأُوصِيكُمَا بِتَقْوَى اللَّهِ، وَ أَلَّا تَبْغِيَا الدُّنْيَا وَ إِنْ بَغَتْكُمَا، وَ لَا تَأْسَفَا عَلَى شَيْءٍ مِنْهَا زُوِيَ عَنْكُمَا، وَ قُولَا بِالْحَقِّ، وَ اعْمَلَا لِلْأَجْرِ، وَ كُونَا لِلظَّالِمِ خَصْماً وَ لِلْمَظْلُومِ عَوْناً. أُوصِيكُمَا وَ جَمِيعَ وَلَدِي وَ أَهْلِي وَ مَنْ بَلَغَهُ كِتَابِي بِتَقْوَى اللَّهِ، وَ نَظْمِ أَمْرِكُمْ\nترجمه:\nوصيتى از آن حضرت (ع) به حسن و حسين عليهما السلام هنگامى كه ابن ملجم (لعنه الله) او را ضربت زد:\nشما را به ترس از خدا وصيت مى كنم و وصيت مى كنم كه در طلب دنيا مباشيد، هر چند، دنيا شما را طلب كند، بر هر چه دنيايى است و آن را به دست نمى آوريد يا از دست مى دهيد، اندوه مخوريد. سخن حق بگوييد و براى پاداش آخرت كار كنيد. ظالم را دشمن و مظلوم را ياور باشيد.\nشما دو تن و همه فرزندان و خاندانم را و هر كس را كه اين نوشته به او مى رسد، به ترس از خدا و انتظام كارها و آشتى با يكديگر سفارش مى كنم.\nتفسیر:\n🔵موضوع نامه: وصیت حضرت بعد از ضربت خوردن\nدر نهج البلاغه چهار وصیت از حضرت علی علیه السلام در \nخطبه ۱۴۹،نامه۲۳،نامه۲۴،نامه ۴۷  آورده شده  است.\n✅امام علی علیه السلام چه درهنگام ضربت خوردن چه بعد از آن و در موارد متعددی در سالها پیش از آن به این نکته اشاره کرده بودند که «قَتَلَنِی ابْنُ الْیَهُودِیَّهِ» \nمرا فرزند زن یهودی به شهادت می‌رساند، البته مکررا در مقابل خود شخص ابن ملجم وقتی که برای خدمت به نزد امام آمده بود ذکر کردند و او منکر این امر بود تا اینکه در نهایت تاریخ آن را ثابت کرد. \n⏪نقش یهود در شهادت معصومین علیهم السلام چه پیامبر خاتم و چه امام علی علیه السلام وامام حسین علیه السلام و… غیر قابل انکار است. \n✅نقل است از صعصه بن صوحان که  هنگامی که حضرت ضربت خورده بودند « استأذن علی علی علیه السلام »اجازه خواست که به محضر حضرت شرفیاب شود امام مجتبی علیه السلام فرمودند حضرت فرموده کسی را راه ندهیم من گفتم حال حضرت چگونه است پیغام من به ایشان بدهید که اگر زنده ماندید مورد رحمت خدا باشید اگر هم به دیدار خدا رفتید مورد رحمت آپ باشید که شما جز خدا ندیدید و جز برای او کار نکردید .\nامیر علیه السلام به او پیغام داد که که به او بگویید صعصعه ؛\n «أنت یرحمک الله فلقد کنت خفیف المئونه کثیر المعونه» \nو خداوند تو را هم مورد رحمتش قرار دهد؛ تو حقیقتا کم زحمت بودی، ولی نصرت و یاری بسیار به ما دادی \nسپس صعصعه می  گوید: \n«ثُمَّ جُمِعَ لَهُ أَطِبَّاءُ الْکُوفَهِ فَلَمْ یَکُنْ مِنْهُمْ أَعْلَمُ بِجُرْحِهِ مِنْ أَثِیرِ بْنِ‏ عَمْرِو بْنِ هَانِی السَّلُولِیِّ…»\nاطبای کوفه جمع شدند حاذق ترین آنها که اثیر بن عمرو  بود  رگی از جگر سفید گوسفند جدا و بر جراحت فرق حضرت گذاشت و گفت:\n « اعهد عهدک، فان عدو اللّه قد وصلت ضربته الی ام راسک»\n ای علی (ع)، و صیت های خود را بگو، زیرا ضربه این دشمن خدا به مغز سر سرایت کرده است.\nحضرت  به حسنین  علیهما السلام و محمدبن حنفیه و فرزندان دیگر وصیت فرمودند که در ادامه در نامه ۴۷ متن آن را می خوانیم .\nمن وصیه له ( علیه السلام ) للحسن و الحسین ( علیهما السلام ) لما ضربه ابن ملجم لعنه الله :\n💠أُوصِیکُمَا بِتَقْوَى اللَّه\n(ای حسن و ای حسین !) شما را  به تقوای الهی سفارش می کنم.\n_این کلمات چکیده عمر حضرتند و چه جالب که با تاکید بر رعایت تقوا آغاز شده است. \n💠 وَ أَلَّا تَبْغِیَا الدُّنْیَا وَ إِنْ بَغَتْکُمَ\nفرزندانم به طرف دنیا حرکت نکنید\n [لا تَبْغِیَا‌] ،دنیا خواه نشوید گرچه دنیا خود را در معرض شما قرار دهد. \n✅البته این  کلام حضرت مصداق کسانی نیست  که وقتی  نمی توانند دنیا را  به دست آورند به ناچار لباس زهد می پوشند !\n✅نکته دیگر این است که در نهج البلاغه در کلام حضرت هم در باب مذمت دنیا هم در باب مدح دنیا مطالبی را حضرت فرموده اند .و این نشان از خوب بودن جلوه ای از دنیا در مقابل جلوه ی بد دنیا دارد .\nاینکه انسان به دنبال فرهم کردن ضروریات زندگی و رفاه نسبی در زندگی باشد این جلوه خوب دنیا است ولی مشکل وقتی ایجاد میشود که انسان به دنبال رفاه مطلق ،تجمل گرایی افراطی باشد .\n🔺 خداوند هم در ایه ۲۰ سوره حدید \n میفرماید: \n« و ما الْحَیَاهُ الدُّنْیَا إِلَّا مَتَاعُ الْغُرُورِ …» \nو باری، بدانید که زندگانی دنیا جز متاع فریب و غرور چیزی نیست.\n⏪اینجاست که حتی  بر کسانی که مسئولیت در حکومت اسلامی دارند  لازم است در حد فقیرترین مردم زندگی کنند .چنانچه نمونه ای از آن در نامه 45 خطاب حضرت به عثمان بن حنیف ،آورده شد.\n💠 وَ لَا تَأْسَفَا عَلَى شَیْ‌ءٍ مِنْهَا زُوِیَ عَنْکُمَ\n(وقتی دنیا از دست شما رفت) آنچه از دست شما رفت [زُوِیَ]تاسف نخورید. \n🔺در قرآن سوره حدید آیه ۲۳\n«لِکَیْلَا تَأْسَوْا عَلَى مَا فَاتَکُمْ وَلَا تَفْرَحُوا بِمَا آتَاکُمْ…»\n بر آنچه از دست شما رفته است اندوه نخورید و بر آنچه [خدا] به شما داده است، شادمان نشوید. \n🔺درحکمت ۴۳۹ فرمود:\n«الزُّهْدُ کُلُّهُ بَیْنَ کَلِمَتَیْنِ مِنَ الْقُرْآنِ، قَالَ اللَّهُ سُبْحَانَهُ: “لِکَیْلا تَأْسَوْا عَلى ما فاتَکُمْ وَ لا تَفْرَحُوا بِما آتاکُمْ”» \nهمه زهد، میان دو کلمه از قرآن قرار گرفته است. خداى تعالى مى فرماید: «تا بر آنچه از دستتان مى رود اندوهگین نباشید و بدانچه به دستتان مى آید شادمانى نکنید.\n✅البته نگاه عبرتی به گذشته که انسان چه کاری می توانسته انجام دهد و در صدد انجام آن جهت جبران بر آید ،خوب است \n🔺در المنثور سیوطی روایت پیرمردی ذکر شده که رسول خدا فرمود از صحابی بهشتی است. \nشخصی که زرنگ بود و می‌خواست دلیل بهشتی بودن او  را بداند نزد او به مدت سه روز مهمان شد ولی نکته خاصی در اعمال او ندید از خودش سوال کرد او هم با اجازه رسول خدا در پاسخ این را گفت که :\n «لو کانت الدنیا لی فأخذت منی لم احزن علیها   و لو  اعطیتها   لم أفرح بها\nدنیا را به من بدهند خوشحال نمیشوم و اگر از من بگیرند ناراحت و غمگین نمی‌شوم. \n«و  ابیت ولیس فی قلبی غل علی احد »\nو شبها که می‌خوابم  در قلبم حسادت، کینه و گلایه و سوء ظنی به کسی ندارم.\n🔺در نامه ۲۲  حضرت به عبدالله بن عباس می فرماید که ابن عباس می‌گوید:\n«ما انتفعتُ بکلام بعد کلام رسول الله صلى اللّه علیه و آله، کإنتفاعی بهذا الکلام!\n پس از سخن رسول الله (ص) از هیچ سخنى بدین پایه سود نبرده\nأَمَّا بَعْدُ، فَإِنَّ الْمَرْءَ قَدْ یَسُرُّهُ دَرْکُ مَا لَمْ یَکُنْ لِیَفُوتَهُ، وَ یَسُوؤُهُ فَوْتُ مَا لَمْ یَکُنْ لِیُدْرِکَهُ؛ \n گاه آدمى را دست یافتن به چیزى که براى او مقدّر بوده و قرار بوده متعلق به او باشد ، شادمان مى سازد، و گاه از دست دادن چیزى که دست یافتن به آن برایش مقدر نبوده است و قرار نبوده به او داده شود ، غمگین مى کند.\n💠 وَ قُولَا بِالْحَقِّ\nسخن به حق بگویید. \nرعایت جانب حق در همه موارد. \n🔺حضرت علی علیه السلام فرمودند در دسته شمشیر پیامبر صلی الله علیه و آله کاغذی یافتیم که سه جمله نوشته شده  بود :\nصِل مَن قَطَعَک:اگر کسی قطع رابطه کرد تا شرایط هست وصلت بر قرار کن \nقُلِ الحقَّ ولو على نفسِکَ : حق را بگو حتی اگر بر ضرر تو باشد. \nأحْسِن إِلَى مَنْ أَسَاءَ إِلَیْکَ :خوبی در حق کسی که به تو بدی کرده ،نما .\n✅شمشیر نماد مبارزه و کشت و کشتار است ولی حضرت در دسته شمشیرش تاکید بر رعایت اخلاق و مهربان بودن دارند. \n🔺روایت از امام باقر علیه السلام که فرمودند پدرم علی بن الحسین در اواخر عمر خود مرا در آغوش گرفت و مطلبی فرمود که حسین بن علی پدرش در اواخر عمر و ایشان از علی علیه السلام شنیدند که \n«یا بُنَیَّ، اِصْبِرْ عَلَى الْحَقِّ وَ اِنْ کانَ مُرّا؛» حدیث. فرزندم! در راه حق، صبور باش، حتّى اگر [صبورى] تلخ باشد.\n💠وَ اعْمَلَا لِلْأَجْرِ\nهر کاری می خواهید انجام دهید  برای اجر باشد قبل انجام  تأمل کنید که جزای آخرتی داشته باشد .\n💠 کُونَا لِلظَّالِمِ خَصْماً وَ لِلْمَظْلُومِ عَوْنا\nخطاب به  همه انسانها! برای انسان ظالم دشمن و برای مظلوم یاور و مدد کار باشید \n🔺روایت از پیامبر صلی الله علیه و آله:\n«مَنْ أَصْبَحَ لا یَهْتَمُّ بِأُمورِ الْمُسْلمینَ فَلَیْسَ بِمُسْلِمٍ» \nهر کسی که، صبح کند و اهتمامی به امور مسلمانان نداشته باشد، مسلمان نیست\nومن سمع رجلا ینادی یا للمسلمین فلم یجبه فلیس بمسلم» \nهر کس بشنود که مردی مسلمانان را به کمک می طلبد و او اجابت نکند آن کس مسلمان نیست. \n🔺امام سجاد در دعا دارند که \n«اللّهُمّ إِنّی أَعْتَذِرُ إِلَیْکَ مِنْ مَظْلُومٍ ظُلِمَ بِحَضْرَتِی فَلَمْ أَنْصُرْهُ» \nخدایا من از اینکه  به مظلومی در حضور من ظلم شود و او را یاری نکنم ،از تو عذر می خواهم .\n🔺حضرت در خطبه ۳۷فرمود :\n «الذَّلِیلُ عِنْدِی عَزِیزٌ حَتَّى آخُذَ الْحَقَّ لَهُ، وَ الْقَوِیُّ عِنْدِی ضَعِیفٌ حَتَّى آخُذَ الْحَقَّ مِنْه» \nذلیل و ستمدیده نزد من عزیز است تا مادامى که حقش را از ظالم بستانم. قوى و ستمگر نزد من خوار است تا حق مظلوم را از او بستانم.\n🔺خطبه ۱۳۶: \n « أَیُّهَا النَّاسُ أَعِینُونِی عَلَى أَنْفُسِکُمْ، وَ ایْمُ اللَّهِ لَأُنْصِفَنَّ الْمَظْلُومَ مِنْ ظَالِمِهِ وَ لَأَقُودَنَّ الظَّالِمَ بِخِزَامَتِهِ، حَتَّى أُورِدَهُ مَنْهَلَ الْحَقِّ وَ إِنْ کَانَ کَارِهاً» \n اى مردم، مرا یارى کنید، هر چند، خلاف میلتان باشد، سوگند به خدا، حق ستمدیده را از ستمگر مى ستانم و افسار ظالم را آنجا که باید میکشم( به طرف حق) و گردن ظالم را میشکنم حتی با اینکه خود او هم نخواهد \n❇️در کتاب کشف الغمه و تمام نهج البلاغه و برخی  کتب دیگر هم  جملاتی آمده که سید رضی در نامه ۴۷ نیاورده است ؛\n«هل حفظت ما اوصیت به اخویک؟قال:نعم،\nاى محمد آیا به حافظه خود سپردى آنچه را که دو برادرت را بدان وصیت کردم؟\nگفت:آرى، \nقال:فانى اوصیک بمثله و اوصیک بتوقیر اخویک لعظم حقهما علیک فلا توثق امرا دونهما،ثم قال:اوصیکما به فانه شقیقکما و ابن أبیکما و قد علمتما ان اباکما کان یحبه…»\nامام (ع) بدو فرمود:پس بدان که من تو را نیز به همانها وصیت مى‏کنم و نیز به تو سفارش مى‏کنم که احترام برادرانت را نگه دارى زیرا حق آن دو بر تو بزرگ است،پس کارى را بدون نظر آنها انجام ندهى آن‏گاه به حسن و حسین (ع) نیز فرمود:شما را نیز بدو سفارش مى‏کنم زیرا که وى برادر شما و پسر پدر شماست و بخوبى دانسته‏اید که پدرتان او را پیوسته دوست می‌داشت.\n✳️در مورد محمد بن حنفیه:\nفرزند امیرالمومنین و خوله حنفیه است.\nدر مورد محمد بن حنفیه دو نظر کاملا متفاوت و متضاد در تاریخ مطرح است، بعضی او را ثقه و عادل میدانند و برخی او را منحرف.\n♦️دلایل قائلین به وثاقت او:\n1⃣کَانَ أَمِیرُ الْمُؤْمِنِینَ یَقُولُ إِنَّ الْمَحَامِدَهَ تَأْبَى أَنْ یُعْصَى اللَّهُ عَزَّ وَ جَلَّ \nچهار محمد مانع نافرمانی خدا می‌شوند؛\nقُلْتُ وَ مَنِ الْمَحَامِدَهُ \nگفتند این چهار محمد کیستند:\nقَالَ مُحَمَّدُ بْنُ جَعْفَرٍ وَ مُحَمَّدُ بْنُ أَبِی بَکْرٍ وَ مُحَمَّدُ بْنُ أَبِی حُذَیْفَهَ وَ مُحَمَّدُ بْنُ أَمِیرِ الْمُؤْمِنِینَ ع\n محمد بن جعفر طیار، محمد بن ابی بکر، محمد بن حنفیه و محمد بن ابی حذیفه.\n2⃣کلام حضرت در نامه 47  وصیت نامه حضرت است و در جملاتی که خوانده شد، شدت علاقه امام علیه السلام  به او بیان شده است \n3⃣نامه امام حسین در جریان کربلا که نشان از جایگاه او در نزد امام حسین دارد:\nبِسْمِ اللَّهِ الرَّحْمنِ الرَّحِیمِ هَذَا مَا أَوْصَى بِهِ الْحُسَیْنُ بْنُ عَلِیِّ بْنِ أَبِی طَالِبٍ إِلَى أَخِیهِ مُحَمَّدٍ الْمَعْرُوفِ بِابْنِ الْحَنَفِیَّهِ…….. وَ أَنِّی لَمْ أَخْرُجْ أَشِراً وَ لَا بَطِراً وَ لَا مُفْسِداً وَ لَا ظَالِماً وَ إِنَّمَا خَرَجْتُ لِطَلَبِ الْإِصْلَاحِ فِی أُمَّهِ جَدِّی ص أُرِیدُ أَنْ آمُرَ بِالْمَعْرُوفِ وَ أَنْهَى عَنِ الْمُنْکَرِ وَ أَسِیرَ بِسِیرَهِ جَدِّی وَ أَبِی‏ عَلِیِّ بْنِ أَبِی طَالِب‏ \nطبق برخی نقل امام با این نامه محمد بن حنفیه را جاسوس و نماینده خود در مدینه قرار داد.\n♦️ادله ی مخالفین:\n1⃣ادعای امامت: \nکافی ج1 ص348: لَمَّا قُتِلَ الْحُسَیْنُ ع أَرْسَلَ مُحَمَّدُ بْنُ الْحَنَفِیَّهِ إِلَى عَلِیِّ بْنِ الْحُسَیْنِ ع فَخَلَا بِهِ فَقَالَ لَهُ یَا ابْنَ أَخِی قَدْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ص دَفَعَ الْوَصِیَّهَ وَ الْإِمَامَهَ مِنْ بَعْدِهِ إِلَى أَمِیرِ الْمُؤْمِنِینَ ع ثُمَّ إِلَى الْحَسَنِ ع ثُمَّ إِلَى الْحُسَیْنِ ع وَ قَدْ قُتِلَ أَبُوکَ رَضِیَ اللَّهُ عَنْهُ\nوَ صَلَّى عَلَى رُوحِهِ وَ لَمْ یُوصِ وَ أَنَا عَمُّکَ وَ صِنْوُ أَبِیکَ وَ وِلَادَتِی مِنْ عَلِیٍّ ع فِی سِنِّی وَ قَدِیمِی أَحَقُّ بِهَا مِنْکَ فِی حَدَاثَتِکَ فَلَا تُنَازِعْنِی فِی الْوَصِیَّهِ وَ الْإِمَامَهِ…… \n بعد از شهادت امام حسین، محمد حنفیه نزد امام سجاد رفت و بعد از تنها شدنشان به حضرت گفت همانطور که میدانی پیامبر امامت و لایت را بعد از خودشان به امیرالمومنین پدر من دادند و بعد از امیرالمومنین فرزندانشان حسن و حسین امام شدند پس حالا بعد از امام حسین باتوجه به اینکه من فرزند علی علیه السلام هستم و عمو ی تو و از نظر سن از تو بزرگترم پس حق امامت بعد از پدرت باید برای فرزندان علی بماند. در نهایت حضرت با او صحبت کردند و سنگ حجر الاسود بر امامت امام سجاد شهادت داد تا او قانع شد که امام سجاد علیه السلام امام چهارم شیعیان هست. \n2⃣طبق برخی نقل ها او ادعای مهدویت کرد. \n3⃣طبق برخی نقل ها از فرقه کیسانیه که او را امام میدانستند اعلان برائت نکرد.\n⏪ با توجه به احادیث امام صادق شاید بتوان به توبه و بازگشت محمد رسید:\n مَا مَاتَ مُحَمَّدُ بْنُ الْحَنَفِیَّهِ حَتَّى آمَنَ بِعَلِیِّ بْنِ الْحُسَیْنِ عَلَیْهِ السَّلَام‏\nمحمد حنفیه از دنیا نرفت مگر بعد از ایمان به امام سجاد علیه السلام.\n💠أُوصِیکُمَا وَ جَمِیعَ وَلَدِی وَ أَهْلِی وَ مَنْ بَلَغَهُ کِتَابِی بِتَقْوَى اللَّهِ وَ نَظْمِ أَمْرِکُمْ\nسفارش میکنم شما حسنین و جمیع فرزندان و هر کس نامه من به او می رسد را به تقوای پروردگار و نظم. \nهمانگونه که امام در ابتدا و وسط و انتهای کلامشان به رعایت تقوا اشاره دارند و ماهم باید تقوا الهی را در همه جای زندگی رعایت کنیم. \n✅نظم دو معنا دارد.:\n1⃣به معنای انضباط که یعنی با برنامه زندگی خود را پیش بردن برای رسیدن به اهداف که چون نظام عالم هم نظم دارد و یکی از راههای اثبات خدا نظم است کسی که خارج از نظم حرکت کند بر خلاف قانون عالم حرکت کرده است و به مقصد نمیرسد .\n🔺حتی حضرت در نامه ۵۳ خطاب به مالک اشتر می‌فرماید :\nإِیَّاکَ وَالْعَجَلَهَ بِالاُْمُورِ قَبْلَ أَوَانِهَا، أَوِ التَّسَقُّطَ فِیهَا عِنْدَ إِمْکَانِهَا، أَوِ اللَّجَاجَهَ فِیهَا إِذَا تَنَکَّرَتْ، أَوِ الْوَهْنَ عَنْهَا إِذَا اسْتَوْضَحَتْ، فَضَعْ کُلَّ أَمْر مَوْضِعَهُ، وَأَوْقِعْ کُلَّ أَمْر مَوْقِعَهُ\n هرگز در کارى که وقت آن فرا نرسیده شتاب نکن، یا کارى که وقت آن رسیده سستى نورز، و یا در چیزى که (حقیقت آن) روشن نیست ستیزه جویى نکن و یا در کارهاى واضح و آشکار کوتاهى نکن تلاش کن تا هر کارى را در جاى خود، و در زمان مخصوص به خود، انجام دهى.\n2️⃣در بررسی نهج البلاغه حضرت «امر »را در مواقع زیاد به معنای حکومت کار برده اندو با توجه به تناسب معنایی بیشتری که دارد حضرت توصیه به نظم در حکومت و اینکه اگر شرایطش فراهم  است ،حکومت  متعلق به حسنین علیهما السلام است وباید آن را از دست غاصبین بازپس گرفت می باشد. \nغفرالله لی و لکم الحمدلله رب العالمین","بخش  دوم\nمتن:\nوَ صَلَاحِ ذَاتِ بَيْنِكُمْ، فَإِنِّي سَمِعْتُ جَدَّكُمَا (صلی الله علیه وآله) يَقُولُ: صَلَاحُ ذَاتِ الْبَيْنِ أَفْضَلُ مِنْ عَامَّةِ الصَّلَاةِ وَ الصِّيَامِ.\nاللَّهَ اللَّهَ فِي الْأَيْتَامِ، فَلَا تُغِبُّوا أَفْوَاهَهُمْ وَ لَا يَضِيعُوا بِحَضْرَتِكُمْ. اللَّهَ اللَّهَ فِي جِيرَانِكُمْ، فَإِنَّهُمْ وَصِيَّةُ نَبِيِّكُمْ مَا زَالَ يُوصِي بِهِمْ حَتَّى ظَنَنَّا أَنَّهُ سَيُوَرِّثُهُمْ. وَ اللَّهَ اللَّهَ فِي الْقُرْآنِ لَا يَسْبِقُكُمْ بِالْعَمَلِ بِهِ غَيْرُكُمْ.\nترجمه:\nكه از رسول خدا (صلى الله عليه و آله) شنيدم كه مى گفت: آشتى با يكديگر برتر است از يك سال نماز و روزه.\nخدا را خدا را، که يتيمان را رعايت کنيد، نکند آنها گاهى سير و گاهى گرسنه بمانند و در حضور شما ضايع شوند. خدا را خدا را، که در مورد همسايگان خود خوش رفتارى کنيد، چرا که آنان مورد توصيه پيامبر شما هستند و او همواره نسبت به همسايگان سفارش مى فرمود تا آنجا که ما گمان برديم به زودى آنها را در ارث شريک خواهد کرد. خدا را خدا را، که عمل به احکام قرآن را فراموش ننماييد، نکند ديگران در عمل به آن بر شما پيشى گيرند.\nتفسیر:\n🔵موضوع نامه: وصیت نامه حضرت بعد از ضربت خوردن در جمع فرزندانشان خطاب به همه انسانها در طول تاریخ. \n💠 وَ صَلَاحِ ذَاتِ بَیْنِکُمْ\n(به فرزندانم و هر که این نامه به  دست او می رسد) ،وصیت می کنم که بین خود صلح و آشتی برقرار کنید \nاصلاح ذات تایید یک عنوان می باشد که به طور وسیع در روایات و قرآن به آن اشاره شده .جامعه بشری جامعه تضادها می باشد ،در گیری ها وجود خواهند داشت اما در فضای خانواده ،همسایگی و … باید آن را به حداقل رساند اگر هم نزاع و مشکلی رخ داد با پادر میانی رفع نمود.\nنامه ۴۷ عصاره کلام حضرت در نهج البلاغه می باشد که اصول کلی دینداری ،فلاح در این نامه آمده است .\n❇️ذکر چند روایت و آیه قرآن  درباره «اصلاح ذات البین»\n1️⃣  جَعَلَ النَّبِىُّ(صلى الله علیه و آله و سلم) اَجْرَ المُصْلح بَیْنَ النّاسِ کَاَجْرِ المُجاهِدِ عِنْدَ النّاسِ\nحضرت رسول اکرم صلی الله علیه و آله: کسی که بین دو نفر آشتی دهد اجر مجاهد در میدان نبرد را دارد .\n2️⃣پیامبر اکرم صلی الله علیه و آله:\n مَن مَشی فی صُلحٍ بَینَ اِثنینِ صلّی عَلَیهِ مَلائِکَهُ اللهِ حتّی یَرجِعَ و اُعطِیَ أَجرَ لَیلَهِ القَدرِ\nکسی که برای آشتی بین دو نفر حرکت کند ملایکه بر او درود و صلوات می فرستند تا برگردد و ثواب شب قدر را می‌برد .( ثواب عبادت  شب قدر اندازه یک عمر عبادت با اخلاص و مقبول است)\n3️⃣آیه ۲۲۴ سوره بقره \n«وَلَا تَجْعَلُوا اللَّهَ عُرْضَهً لِأَیْمَانِکُمْ أَنْ تَبَرُّوا وَتَتَّقُوا وَتُصْلِحُوا بَیْنَ النَّاسِ وَاللَّهُ سَمِیعٌ عَلِیمٌ»\nزنهار نام خدا را هدف سوگندهای خود مکنید تا (با این سوگندهای راست و دروغ) از حقوقی که مردم را بر شماست برائت جوئید و خود را نیکوکار و پرهیزکار قلمداد کنید و مصلح میان مردم جلوه دهید؛ و خدا (راست و دروغ و نیک و بد را) شنوا و داناست\n4️⃣از امام صادق علیه السلام ذیل این آیه روایت داریم که :\n إِذَا دُعِیتَ لِصُلْحٍ بَیْنَ اثْنَیْنِ فَلَا تَقُلْ عَلَیَّ یَمِینٌ أَلَّا أَفْعَلَ\nامام صادق (علیه السلام) وقتی تو را برای آشتی‌دادن بین دو نفر، دعوت کردند، نگو: «من قسم خورده‌ام که این کار را نکنم».\n5️⃣مرحوم کلینی در کافی شریف باب اصلاح بین الناس روایاتی آورده اند :\nامام صادق علیه السلام :\nصَدَقهٌ یُحِبُّها اللّه ُ : إصلاحٌ بینَ الناسِ إذا تَفاسَدُوا، و تَقارُبٌ بَینَهِم إذا تَباعَدُوا .\nصدقه اى که خدا آن را دوست دارد عبارت است از : اصلاح میان مردم هرگاه رابطه شان تیره شد، و نزدیک کردن آنها به یکدیگر هرگاه از هم دور شدند .\n6️⃣امام صادق علیه السلام :\n إِذَا رَأَیْتَ بَیْنَ اثْنَیْنِ مِنْ شِیعَتِنَا مُنَازَعَهً فَافْتَدِهَا مِنْ مَالِی‌\nوقتی دیدید بین شیعیان من اختلاف افتاده از پولهای من بدهید ، بین آنها را اصلاح کنید .\n7️⃣ این  مطلب را حضرت  به  مُفَضَّل\nفرموده بود . \nنقل اَست از مُفَضَّل که:\nوَ أَنَا وَ خَتَنِی‌ نَتَشَاجَرُ فِی مِیرَاثٍ فَوَقَفَ عَلَیْنَا سَاعَهً\nمفضل می گوید:  در کوچه دیدم دو نفر از شیعیان  در مسایل مالی دچار  اختلاف و نزاع گردیده اند\n ثُمَّ قَالَ لَنَا تَعَالَوْا إِلَى الْمَنْزِلِ فَأَتَیْنَاهُ فَأَصْلَحَ بَیْنَنَا بِأَرْبَعِمِائَهِ دِرْهَمٍ فَدَفَعَهَا إِلَیْنَا مِنْ عِنْدِهِ حَتَّى إِذَا اسْتَوْثَقَ کُلُّ وَاحِدٍ مِنَّا مِنْ صَاحِبِهِ قَالَ أَمَا إِنَّهَا لَیْسَتْ مِنْ مَالِی وَ لَکِنْ أَبُو عَبْدِ اللَّهِ ع أَمَرَنِی.\n من مبلغ پول دادم و آنها را به منزل بردم  و گفتم امام صادق علیه السلام امر فرمودند.\n إِذَا تَنَازَعَ رَجُلَانِ مِنْ أَصْحَابِنَا فِی شَیْ‌ءٍ أَنْ أُصْلِحَ بَیْنَهُمَا وَ أَفْتَدِیَهَا مِنْ مَالِهِ فَهَذَا مِنْ مَالِ أَبِی عَبْدِ اللَّهِ \n  هرگاه دیدید اختلاف  بین شیعیان ما افتاد از مال من به آنها بدهید تا صلح کنند .\n8️⃣پیامبر اکرم صلی الله علیه و آله:\nاَلا اُخْبِرُکُمْ بِاَفْضَلَ مِنْ دَرَجَهِ الصّیامِ وَ الصَّلاهِ وَ الصَّدَقَهِ؟ صَلاحُ ذاتِالْبَیْنِ، فَاِنَّ فَسادَ ذاتِ الْبَیْنِ هِىَ الْحالِقَهُ.\nآیا به چیزى با فضیلت تر از نماز و روزه و صدقه (زکات) آگاهتان نکنم؟ و آن اصلاح میان مردم است، زیرا تیره شدن رابطه بین مردم ریشه کن کننده دین است.\n✅در نهج البلاغه در خطبه ۲۳ آمده که:\nأَیُّهَا النَّاسُ إِنَّهُ لَا یَسْتَغْنِی الرَّجُلُ وَ إِنْ کَانَ ذَا مَالٍ عَنْ [عَشِیرَتِهِ] عِتْرَتِهِ\nاى مردم، آدمى هر چند توانگر بود، از عشیره خویش و دفاع آنان از او، به دست و زبان، بى نیاز نباشد.\n⏪وقتی انسان حمایت از خانواده  را نداشته باشد به دشمن پناه می برد.\n💠فَإِنِّی سَمِعْتُ جَدَّکُمَا (صلى الله علیه وآله) یَقُولُ صَلَاحُ ذَاتِ الْبَیْنِ أَفْضَلُ مِنْ عَامَّهِ الصَّلَاهِ وَ الصِّیَامِ\nبه راستی از رسول اکرم صلی الله علیه و آله شنیدم که می فرمود: آشتی برقرار کردن بین مردم برتر از نماز و روزه عامه است\nعام دو معنا :\n1️⃣به معنای سال:یک اصلاح ذات البین از یکسال نماز و روزه مستحبی مقبول  برتر است \n2️⃣به معنای همه گیر \nیک اصلاح ذات البین به اندازه تمام نماز و روزه های مستحبی ثواب دارد\nاز این جای نامه به بعد حضرت جملات را با لفظ الله الله به جهت اهمیت مطالب به معنای خدا را در نظر داشتن ،به خدا قسم ،بیان می کنند. \n💠اللَّهَ اللَّهَ فِی الْأَیْتَامِ \nشما را به خدا قسم که حواستان به یتیمان باشد \n💠فَلَا تُغِبُّوا أَفْوَاهَهُمْ\nغذا رساندن به آنها را یک در میان انجام ندهید. \nبرنامه ایتام و رفع و رجوع امور آنها باید مرتب مد نظر شما باشد \nتُغِبُّوا(یک در میان کاری انجام دادن )\n✅حتی اگر در توان انسان نیست جهت مداومت در این امر دیگران را شریک  کند\n💠وَ لَا یَضِیعُوا بِحَضْرَتِکُمْ\nمبادا حق ایتام در حضور شما ضایع شود. \n\n❇️ذکر چند روایت و آیه در موضوع ایتام :\n1️⃣آیه ۹ و ۱۰سوره نساء:\nوَلْیَخْشَ الَّذِینَ لَوْ تَرَکُوا مِنْ خَلْفِهِمْ ذُرِّیَّهً ضِعَافًا خَافُوا عَلَیْهِمْ فَلْیَتَّقُوا اللَّهَ وَلْیَقُولُوا قَوْلًا سَدِیدًا\nو باید بترسند (از مکافات عمل خود) کسانی که اگر کودکان ناتوان از خود باقی می‌گذارند بر آنان بیم دارند، پس باید از خدا بترسند و (در حق ایتام مردم) سخن به اصلاح و درستی گویند.\nإِنَّ الَّذِینَ یَأْکُلُونَ أَمْوَالَ الْیَتَامَىٰ ظُلْمًا إِنَّمَا یَأْکُلُونَ فِی بُطُونِهِمْ نَارًا ۖ وَسَیَصْلَوْنَ سَعِیرًا\nآنان که اموال یتیمان را به ستمگری می‌خورند، در حقیقت آنها در شکم خود آتش جهنّم فرو می‌برند و به زودی در آتش فروزان خواهند افتاد.\n⏪اگر از آینده فرزند خود نگران هستید به فقرا امروز رسیدگی کم ولی اگر امور ایتام و فقرا را به عهده نگیری چه بمیری چه زنده باشی ، حق فرزندانت لگد مال خواهد شد \n2️⃣پیامبر اکرم صلی الله علیه و آله :\n«مَنْ مَسَحَ عَلى رَأْسِ یَتیم کانَ لَهُ بِکُلِّ شَعْرَه تَمُرّ عَلى یَدِهِ نُورٌ یَوْمَ الْقِیامَهِ»\nکسی که به سر بچه یتیم دست بکشد به ازای هر تار مو که از زیر دست او رد می شود خدا نور و حسنه در قیامت برای او قرار می دهد \n3️⃣پیامبر اکرم صلی الله علیه و آله\n « ان الیتیم إذا بکى اهتز له العرش»\n وقتی یتیم گریه کند عرش خداوند به لرزه می‌افتد. \n4️⃣مرحوم کلینی در کافی شریف روایتی دارند :\nجاءَ إلى أمیرِ المُؤمِنینَ علیه السلام عَسَلٌ وتینٌ مِن هَمَدانَ وحُلوانَ ، فَأَمَرَ العُرَفاءَ  أن یَأتوا بِالیَتامى ،\nبراى امیر مؤمنان ، از منطقه هَمَدان و حُلوان ، عسل و انجیر آوردند . به سرشناسان قبایل ، دستور داد که یتیمان [قبیله ]را بیاورند .\n فَأَمکَنَهُم مِنرُؤوسِ الأَزقاقِ  یَلعَقُونَها ، وهُوَ یُقَسِّمُها لِلنّاسِ قَدَحا قَدَحا ،\nآنان را بالاى مَشک هاى عسل ، بُرد تا عسل بِلیسند و خود ، عسل ها را ظرف ظرف ، میان مسلمانان تقسیم مى کرد. با انگشتان مبارک غسل در دهان آنها می گذاشت \n فَقیلَ لَهُ : یا أمیرَ المُؤمِنینَ ، ما لَهُم یَلعَقونَها ؟\nگفته شد: اى امیر مؤمنان ! چرا آنان ، عسل مى لیسند ؟\nفَقالَ : إنَّ الإمامَ أبُو الیَتامى ، وإنَّما ألعَقتُهُم هذا بِرِعایَهِ الآباءِ\nفرمود : «امام ، پدر یتیمان است .همانا به جاى پدرانشان ، آنان را به خوردن عسل وا داشتم» .\nابوالطفیل از یاران و صحابی خاص حضرت نقل می کند وقتیاین صحنه ها را می‌دیدم «لولدت عنی کنت یتیما »دوست داشتم یتیم باشم ،حضرت در دهان من هم عسل بگذارند و برایم پدری کنند\n✅ باید توجه نمود از روی دغدغه باید به ایتام و فقرا کمک کرد  ترحم به تنهایی آفت ها دارد.\n💠 اللَّهَ اللَّهَ فِی جِیرَانِکُمْ فَإِنَّهُمْ وَصِیَّهُ نَبِیِّکُمْ\nدرباره همسایگانتان شما را به خدا قسم میدهم که سفارش و وصیت پیغمبر اکرم صلی الله علیه و آله است. \n💠مَا زَالَ یُوصِی بِهِمْ حَتَّى ظَنَنَّا أَنَّهُ سَیُوَرِّثُهُمْ\nآنقدر مکرر می فرمود که گمان کردیم همسایه از همسایه ارث می‌برد .\n❇️ذکر چند روایت در باب همسایه :\n1️⃣ ویژگی ۶۷ متقین در خطبه متقین حضرت امیر علیه السلام :\nو لَا یُضَارُّ بِالْجَارِ، \nهمسایگان را آزار نمى رساند. \n2️⃣مرحوم کلینی در کافی شریف روایت از رسول اکرم صلی الله علیه و آله ذکر کرده:\nحُرمَهُ الجارِ على الإنسانِ کحُرمَهِ اُمّهِ . \n پیامبر خدا صلى الله علیه و آله :احترام همسایه بر انسان ، همانند احترام مادرش است .\n3️⃣همچنین در کافی آمده:\nو قد ورد فی الروایات عنهم أن یعقوب لما ذهب منه ابن یامین نادی یا رب أما ترحمنی أذهبت عینی و أذهبت ابنی.\n در روایت داریم یعقوب علیه السلام به خدا عرض کرد یوسف و بنیامین  و چشمانم را از من گرفتی بنا است تا کجا اشک بریزم؟ \nفأوحی اللّه الیه لو امتّهما لاحییتهما لک حتی أجمع بینک و بینهما و لکن تذکر الشاه التی ذبحتها و شویتها و أکلتها و فلان إلی جانبک صائم لم تنله منها شیئا قال أبو عبد اللّه: \nخدا فرمود من بچه هایت را اگر هم مرده باشند به تو باز می گردانم چشمت را هم بینا می کنم ولی می دانی باطن این ها چه بوده؟گوسفندی را ذبح کردی و طبخ کردی و  بوی غذا پیچید ولی همسایه تو که روزه دار بود. برای افطار چیزی نداشت .\nأن یعقوب بعد ذلک کان ینادی منادیه کل غداه من منزله علی فرسخ الا من أراد الغذاء فلیأت آل یعقوب\n بعد از آن یعقوب تا یک فرسخ از منزل صدا میزد ؛هر کس گرسنه ،محتاج است بیاید به او غذا دهم . \n4️⃣امام صادق علیه السلام :\nحُسنُ الجِوارِ یَزیدُ فی الرِّزقِ \nخوب  همسایگى کردن، روزى را زیاد مى کند\n✅این گمان اشتباه است که صدقه را از مال خود بر میداریم و کم میشود ،خیر این را خدا برای فقیر جدا نزد ما گذاشته از مال ما چیزی کاسته نمی شود\n5️⃣شعید ثانی فرزندان متعددی را در سنی از دست می‌داد مصیبت بر او سنگین شد،مطالبی را در  کتابی در صبر بر غم عزیزان جمع آوری نمود به نام  «مُسَکّنُ الفُؤاد عِنْدَ فَقْدِ الْأحبّه وَ الْأولاد»\nحدیثی از رسول اکرم صلی الله علیه وآله آورده که حضرت فرمودند:\nقَالَ أَ تَدْرُونَ مَا حَقُّ اَلْجَارِ \nپیامبر صلی الله علیه و آله فرمود : [حقّ همسایه است که ؛\nقَالُوا لاَ قَالَ إِنِ اِسْتَغَاثَکَ أَغَثْتَهُ وَ إِنِ اِسْتَقْرَضَکَ أَقْرَضْتَهُ\nاگر از تو کمک خواست کمکش کنى، اگر از تو قرض خواست به او قرض دهى،\n وَ إِنِ اِفْتَقَرَ عُدْتَ عَلَیْهِ وَ إِنْ أَصَابَتْهُ مُصِیبَهٌ عَزَّیْتَهُ\nاگر نیازمند شد نیازش را برطرف سازى، اگر مصیبتى دید او را دلدارى دهى،\n وَ إِنْ أَصَابَهُ خَیْرٌ هَنَّأْتَهُ وَ إِنْ مَرِضَ عُدْتَهُ \nاگر خیر و خوبى به او رسید به وى تبریک گویى، اگر بیمار شد به عیادتش روى،\nوَ إِنْ مَاتَ تَبِعْتَ جَنَازَتَهُ\nوقتى مُرد در تشییع جنازه اش شرکت کنى،\n وَ لاَ تَسْتَطِیلُ عَلَیْهِ بِالْبِنَاءِ فَتَحْجُبَ اَلرِّیحَ عَنْهُ إِلاَّ بِإِذْنِهِ\nخانه ات را بلندتر از خانه او نسازى تا جلوى جریان هوا را بر او بگیرى مگر آن که خودش اجازه دهد،\n وَ إِذَا اِشْتَرَیْتَ فَاکِهَهً فَأَهْدِ لَهُ فَإِنْ لَمْ تَفْعَلْ فَأَدْخِلْهَا سِرّاً وَ لاَ تُخْرِجْ بِهَا وُلْدَکَ تَغِیظُ بِهَا وُلْدَهُ \nهرگاه میوه اى خریدى براى او تعارف بفرستى و اگر این کار را نکردى مخفیانه میوه را به خانه ات ببر،فرزندت را همراه میوه بیرون میاور که بچه او با دیدن میوه در دست او ناراحت شود،\nوَ لاَ تُؤْذِهِ بِرِیحِ قِدْرِکَ إِلاَّ أَنْ تَغْرِفَ لَهُ مِنْهَا \n با بوى و دود دیگت او را ناراحت نکن مگر آن که مقدارى از غذاى آن را براى او بفرستى.\n6️⃣مرحوم مجلسی در بحار باب حق الجار حدیث از پیامبر صلی الله علیه و آله نقل می کند که :\n «مَنْ خَانَ جَارَهُ شِبْراً مِنَ الْأَرْضِ طَوَّقَهُ اللَّهُ یَوْمَ الْقِیَامَهِ إِلَى سَبْعِ أَرَضِینَ»\n«هر کسى به همسایه‌اش به اندازه یک وجب از زمین او خیانت کند، خداوند آنرا طوقى قرار می‌دهد از اعماق زمین هفتم بر گردنش مى‌نهد تا اینکه در روز قیامت در این حال خدا را ملاقات کند.\nو حضرت فرمود این شخص  \n«حَرَّمَ اَللَّهُ عَلَیْهِ رِیحَ اَلْجَنَّهِ» بوی بهشت را استشمام نمی کند \n(در روایت داریم بوی بهشت تا ۵۰۰ سال مسافت به انسان می رسد ولی به او نمیرسد )\n7️⃣در جلسه ۲۹  شرح نامه ۳۱ نهج البلاغه ذیل جمله\nوَ عَنِ الْجَارِ قَبْلَ الدَّارِ، مطالبی آورده شده بود.\n💠 وَ اللَّهَ اللَّهَ فِی الْقُرْآنِ\nشما را قسم می دهم به خدا که حواستان به قرآن باشد عمل به قرآن ملاک باشد. \n💠 لَا یَسْبِقُکُمْ بِالْعَمَلِ بِهِ غَیْرُکُمْ\nمبادا دیگران که به علی علیه السلام محبت ندارند در عمل به قرآن سبقت چبگیرند \n✅ خود حضرت در عمل به قرآن نمونه کامل بودند .حیات مبارک حضرت با قرآن است .اولین کسی که قرآن را به طور کامل به ترتیب نزول همراه تأویل  ، جمع آوری و کتابت فرمود حضرت بود .\nاینطور نباشدما به کارهایی عمل نکرده باشیم ولی دیگران را به انجام آن امر کنیم .\nدربیش از ۳۰ فراز از حکمتها نامه ها خطبه ها، حضرت از قرآن سخن به میان آورده اند گاهی حضرت آیات قرآن را استشهاد ،گاهی آیات را اقتباس، گاهی فضای قرآنی می آورند .\nچندین کتاب قرآن در نهج البلاغه نوشته شده است. \nحضرت با قرآن با دشمنان احتجاج می‌‌کنند. \n🔺در خطبه ۱۷۶حضرت فرمودند :\nاعْلَمُوا أَنَّ هَذَا الْقُرْآنَ هُوَ النَّاصِحُ الَّذِی لَا یَغُشُّ وَ الْهَادِی الَّذِی لَا یُضِلُّ وَ الْمُحَدِّثُ الَّذِی لَا یَکْذِبُ، \nآگاه باشید همانا این قرآن پند دهنده اى است که نمى فریبد، و هدایت کننده اى است که گمراه نمى سازد، و سخنگویى است که هرگز دروغ نمى گوید.\nوَ مَا جَالَسَ هَذَا الْقُرْآنَ أَحَدٌ إِلَّا قَامَ عَنْهُ بِزِیَادَهٍ أَوْ نُقْصَانٍ، زِیَادَهٍ فِی هُدًى أَوْ نُقْصَانٍ مِنْ عَمًى؛ \nکسى با قرآن همنشین نشد مگر آن که بر او افزود یا از او کاست، در هدایت او افزود و از کور دلى و گمراهى اش کاست.\nوَ اعْلَمُوا أَنَّهُ لَیْسَ عَلَى أَحَدٍ بَعْدَ الْقُرْآنِ مِنْ فَاقَهٍ وَ لَا لِأَحَدٍ قَبْلَ الْقُرْآنِ مِنْ غِنًى،\nآگاه باشید هیچ کس  بعد از قرآن ، فقیر نشود و قبل از انس و عمل به قرآن غنا را  نخواهد چشید.(پول ملاک فقر و غنا نیست)\nغفرالله لی و لکم الحمدلله رب العالمین","بخش سوم\nمتن:\nوَ اللَّهَ اللَّهَ فِي بَيْتِ رَبِّكُمْ لَا تُخَلُّوهُ مَا بَقِيتُمْ، فَإِنَّهُ إِنْ تُرِكَ لَمْ تُنَاظَرُوا. وَ اللَّهَ اللَّهَ فِي الْجِهَادِ بِأَمْوَالِكُمْ وَ أَنْفُسِكُمْ وَ أَلْسِنَتِكُمْ فِي سَبِيلِ اللَّهِ.\nترجمه:\nخدا را خدا را، که نماز را برپا داريد، چرا که ستون دين شماست. خدا را خدا را، که خانه پروردگارتان را به فراموشى نسپاريد و تا زنده هستيد آن را خالى نگذاريد، که اگر زيارت خانه خدا ترک شود به شما مهلت داده نخواهد شد (و بلاى الهى نازل مى گردد). خدا را خدا را، که در جهاد با مال و جان و زبان خويش در راه خداوند کوتاهى نکنيد، (و از هر سه وسيله در اين راه بهره گيريد)\nتفسیر:\n🔵موضوع نامه:وصیت نامه حضرت خطاب به فرزاندانشان و در حقیقت همه بشریت. عصاره نهج‌البلاغه در وصیتنامه‌های حضرت آمده است. \nدر جلسه قبل برحقوق ایتام و همسایه و عمل به قرآن تاکید شد. \n💠 وَ اللَّهَ اللَّهَ فِی الصَّلَاهِ فَإِنَّهَا عَمُودُ دِینِکُمْ.\nشمارا قسم میدهم به خدا که مراقب نماز باشید، چرا که نماز ستون دین شماست. \n❇️روایات در زمینه اهمیت نماز :\nامام باقر علیه السلام میفرمایند: \nالصَّلاَهُ عَمُودُ الدِّینِ مَثَلُهَا کَمَثَلِ عَمُودِ الْفُسْطَاط\nنماز ستون دین است مانند ستون خیمه; \nإِذَا ثَبَتَ الْعَمُودُ ثَبَتَتِ الاَْوْتَادُ وَالاَْطْنَابُ\nهنگامى که ستون خیمه ثابت و برقرار باشد طناب ها و میخ ها کارآیى دارند. \n وَإِذَا مَالَ الْعَمُودُ وَانْکَسَرَ لَمْ یَثْبُتْ وَتِدٌ وَلاَ طُنُبٌ \n و اگر ستون خیمه کج شود یا بشکند از میخ ها و طناب ها کارى ساخته نیست. \n✅ما لفظی به نام قرائت یا تلاوت نماز نداریم، بلکه اقامه نماز را داریم، و این نشان از اهمیت نماز است. \nاقامه صلاه به این معنا است که باید نماز را در تمام ارکان زندگی پیاده کرد و زندگی حول محور نماز باشد، طبق بیان شاعر:\nخوشا آنان که دائم در نمازند. \nنماز توحید است، نماز الحمدللّه و سبحان‌اللّه است، نماز رکوع و سجود است، نماز تواضع و اخلاص است…. \nخوشا به حال کسانی دائما در حال اقامه نمازند و به دو سه دقیقه نماز صبح و نماز ظهر اکتفا نمی‌کنند و تمام زندگی‌شان حول محور نماز است. وبه تعبیر قرآن نماز ذکر است. \n🔺در نهج البلاغه و احادیث ائمه و کلام بزرگان دینمان موارد بسیاری در اهمیت نماز آمده است از جمله خطبه ۱۹۹ نهج‌البلاغه:\n تَعَاهَدُوا أَمْرَ الصَّلَاهِ وَ حَافِظُوا عَلَیْهَا\nمراقب باشیو نماز را برای خودتان حفظ کنید\n وَ اسْتَکْثِرُوا مِنْهَا وَ تَقَرَّبُوا بِهَا\nزیاد نماز بخوانید و خودتان را به نماز نزدیک کنید. \n فَإِنَّهَا کانَتْ عَلَى الْمُؤْمِنِینَ کِتاباً مَوْقُوتاً\nخداوند این نماز را بر مؤمنین واجب ساخته است. \nأَ لَا تَسْمَعُونَ إِلَى جَوَابِ أَهْلِ النَّارِ حِینَ سُئِلُوا- ما سَلَکَکُمْ فِی سَقَرَ \nآیا آیه قرآن را نشنیدید آن زمان که از جهنمیان می‌پرسد چه چیزی موجب جهنمی شدنتان شد. \nقالُوا لَمْ نَکُ مِنَ الْمُصَلِّینَ\nمی‌گویند که ما از نماز گزاران نبودیم. \n(اگر نماز از زندگی کسی رفت خیر و برکت خواهد رفت.) \nدر ادامه خطبه ۱۹۹ نکات بسیاری در زمینه نماز بیان می‌شود که لازم است به آن مراجعه شود از جمله حضرت در بیان اهمیت نماز استناد می‌کند به این حدیث پیامبر‌ که نماز مثل آب جاری است که هر کس هر روز پنج مرتبه خود را در آن میشوید.\n\n💠وَ اللَّهَ اللَّهَ فِی بَیْتِ رَبِّکُمْ لَا تُخَلُّوهُ مَا بَقِیتُمْ، فَإِنَّهُ إِنْ تُرِکَ لَمْ تُنَاظَرُوا \nشما را قسم میدهم به خدا که مراقب خانه خدا باشید، مبادا تا وقتی زنده اید کعبه خالی بماند آگاه باشید اگر خانه خدا را رها کنید:\n1️⃣ به شما مهلت داده نمی شود و دچار عذاب میشوید. ‌[لَمْ تُنَاظَرُوا ] \n 2️⃣ از چشم خدا می افتید. [لَمْ تُنَاظَرُوا] \n_مشکل ما با سعودی نباید مانع رفتن ما به حج بشود. اگر تمایل به مشهد و کربلا بیش از رفتن به حج است باید در این دیدگاه تجدید نظر کرد چرا که حج جایگاه خاص خودش را دارد و باید به همان میزان اشتیاق برای حج رفتن بین مردم باشد. \n🔺إِسْحَاقَ بْنِ عَمَّارٍ قَالَ: قُلْتُ لِأَبِی عَبْدِ اللَّهِ ع\nاسحاق بن عمار به امام صادق علیه السلام گفت:\nإِنَّ رَجُلًا اسْتَشَارَنِی فِی الْحَجِّ وَ کَانَ ضَعِیفَ الْحَالِ \nشخصی که ضعف جسمی یا مالی داشت با من در مورد رفتن به حج مشورت کرد. \nفَأَشَرْتُ إِلَیْهِ أَنْ لَا یَحُجَّ \nگفتم به صلاح نیست شما حج بروید. \nفَقَالَ مَا أَخْلَقَکَ  أَنْ تَمْرَضَ سَنَهً \nامام فرمود چه کار بدی انجام دادی سزاوار است به خاطر این حرف یک سال بیمار شوی. \nقَالَ فَمَرِضْتُ سَنَهً \nاسحاق بن عمار میگوید من یک سال بیمار شدم\n⏪ مرحوم کلینی این روایت را در “باب النوادر” حج آورده یعنی یک قاعده کلی نیست و یک قضیه شخصیه است ولی دلالت بر اهمیت حج میکند.\n🔺مرحوم کلینی در کتاب الحج کافی بابی دارد تحت عنوان:\n بَابُ إِتْبَاعِ الْحَجِّ بِالزِّیَارَهِ \nبعد از اتمام حج باید به زیارت امام رفت(در زمان ظهور امام بایدبعد از انجام اعمال حج به زیارت امام رفت) \n🔺عَنْ أَبِی جَعْفَرٍ قَالَ: \nامام باقر علیه السلام میفرمایند:\n«إِنَّمَا أُمِرَ النَّاسُ أَنْ یَأْتُوا هذِهِ الْأَحْجَارَ، فَیَطُوفُوا بِهَا، ثُمَّ یَأْتُونَا، فَیُخْبِرُونَا بِوَلَایَتِهِمْ، وَ یَعْرِضُوا عَلَیْنَا نَصْرَهُمْ \nمردم خیال کرده اند مامور به طواف سنگ کعبه شده اند ولی امر نشده اند به اعلام ولایتمداری و نصرت ما؟؟؟\nکعبه یک سنگ نشانی است که ره گم نشود/ \nحاجی احرام دگر بند ببین یار کجاست\n🔺عَنْ أَبِی جَعْفَرٍ قَالَ: \nدر روایت دیگری از امام باقر آمده \nتَمَامُ الْحَجِّ لِقَاءُ الْإِمَام‏.\nکامل شدن حج به دیدار با امام است. \nطبق روایت است که امام الزمان هر سال در حج حاضر می‌شوند و به دیدار حجاج می‌روند، هرچند حجاج حضرت را نمی‌شناسند ولی حضرت با آنها ملاقات می‌کنند .\n \n🔺قَالَ عَبْدُ اللَّهِ بْنُ سِنَانٍ، فَأَتَیْتُ أَبَا عَبْدِ اللَّهِ عَلَیْهِ السَّلَامُ، \nعبدالله بن ثنان نزد امام صادق رفتند و پرسیدند:\nفَقُلْتُ: جُعِلْتُ فِدَاکَ، قَوْلُ اللَّهِ عَزَّ وَ جَلَّ:\nجانم به فدایتان خداوند فرمود\n «ثُمَّ لْیَقْضُوا تَفَثَهُمْ وَ لْیُوفُوا نُذُورَهُمْ»؟ حاجیان پس از انجام مناسک باید آلودگی ها را از خود دور کنند و به عهدهایشان وفا کنند\nقَالَ: «أَخْذُ الشَّارِبِ، وَ قَصُّ الْأَظْفَارِ، وَ مَا أَشْبَهَ ذلِکَ». \nامام علیه السلام فرمودند:\nمنظور حلق و تقصیر و چیدن ناخن و… پیامک است. و قسمت دومش هم وفای به عهد است. \nقال: قُلْتُ: جُعِلْتُ فِدَاکَ، إِنَّ ذَرِیحَ الْمُحَارِبِیِّ حَدَّثَنِی عَنْکَ بِأَنَّکَ قُلْتَ لَهُ:\nعبداللّه بن سنان می‌گوید جانم به فدایتان من از ذریح محاربی (از خواص امام باقر، امام صادق، امام کاظم)این گونه شنیدم که شما فرمودید:\n  «لْیَقْضُوا تَفَثَهُمْ»: لِقَاءُ الْإِمَامِ وَ «لْیُوفُوا نُذُورَهُمْ»: تِلْکَ الْمَنَاسِکُ؟\nآلودگی را پاک کردن یعنی دیدار با امام\nو وفای به عهد معنای انجام آن مناسک را دارد؟ \nفَقَالَ: «صَدَقَ ذَرِیحٌ، وَ صَدَقْتَ؛ إِنَّ لِلْقُرْآنِ ظَاهِراً وَ بَاطِناً، وَ مَنْ یَحْتَمِلُ  مَا یَحْتَمِلُ ذَرِیحٌ؟»\nامام فرمودند: ذریح درست می‌گوید ، برای قرآن ظاهر باطنی هست، کجا شخصی مثل ذریح پیدا می‌شود (که آمادگی دریافت چنین معارفی را داشته باشد)؟ \n⏪کمال و حقیقت حج امام است.\n💠وَ اللَّهَ اللَّهَ فِی الْجِهَادِ بِأَمْوَالِکُمْ وَ أَنْفُسِکُمْ وَ أَلْسِنَتِکُمْ فِی سَبِیلِ اللَّهِ.\nشمارا قسم میدهم به خدا که با اموال و جان‌ها و زبانهایتان جهاد کنید. \n✅حضرت جهاد را در سه بخش میدانند:\n1️⃣جهاد مالی:\n(باتوجه به تقدم جهاد مالی بر سایر جهاد ها به اهمیت جهاد پی خواهیم برد) \nآیه 88 توبه: لَٰکِنِ الرَّسُولُ وَالَّذِینَ آمَنُوا مَعَهُ جَاهَدُوا بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ ۚ \nپیامبر و کسانی که با او ایمان آوردند، با اموال و جانهایشان جهاد کردند؛\nوَأُولَٰئِکَ لَهُمُ الْخَیْرَاتُ ۖ وَأُولَٰئِکَ هُمُ الْمُفْلِحُونَ\n همه نیکیها برای آنهاست؛ و آنها همان رستگارانند!\nحضرت فدک را میخواست تا با آن در راه خدا جهاد کند و با آن بنیه مالی، فقرا را جذب کند.\nبرخی حاضرند نشان را بدهند ولی بنیه مالی‌شان را از دست ندهند. \n🔺در آیه 95 نساء فرمود: فَضَّلَ اللَّهُ الْمُجَاهِدِینَ بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ عَلَى الْقَاعِدِینَ دَرَجَهً\nخدا کسانى را که به مال و جان خویش جهاد مى‌کنند بر آنان که از جنگ سر مى‌تابند به درجتى برترى داده است.\n و بعد فرمود: وَفَضَّلَ اللَّهُ الْمُجَاهِدِینَ عَلَى الْقَاعِدِینَ أَجْرًا عَظِیمًا\n و خدا همه را وعده‌هاى نیکو داده است. و جهادکنندگان را بر آنها که از جهاد سر مى‌تابند به مزدى بزرگ برترى نهاده است\n⏪ مجاهدی که هم پول میدهد هم خون، بر قاعدین افضلیت دارد.\n2️⃣جهاد جانی:\nخطبه 182:\nأَیْنَ إِخْوَانِی الَّذِینَ رَکِبُوا الطَّریِقَ، وَ مَضَوْا عَلَى الْحَقِّ؟ أَیْنَ عَمَّارٌ؟ وَ أَیْنَ ابْنُ التَّیِّهَانِ؟ وَ أَیْنَ ذُو الشَّهَادَتَیْنِ؟\nکجایند برادران من همانها که در مسیر صحیح گام نهادند و در راه حق پیش رفتند. عمار کجاست؟ ابن تیهان کجاست؟ \nذو شهادتین کجاست؟ \n⏪راه حق راه شهادت است. وامثال عمار را می‌طلبد. \n🔺خطبه ۲۷ : أَمَّا بَعْدُ فَإِنَّ الْجِهَادَ بَابٌ مِنْ أَبْوَابِ الْجَنَّهِ فَتَحَهُ اللَّهُ لِخَاصَّهِ أَوْلِیَائِهِ وَ هُوَ لِبَاسُ التَّقْوَى….. \nجهاد بابی از ابواب بهشت است که خداوند آن را برا بندگان خالص قرار داد، چراکه آن را لباس تقوا قرار داد(بالاترین حد از تقوا جهاد با جان است‌) \n⏪تقوا زره بدنهاست در هنگامه جهاد. کسی که جهاد ندارد مثل این است که لخت و بدون پوش به جهاد برود. \nدر ادامه میفرماید‌:\n فَمَنْ تَرَکَهُ رَغْبَهً عَنْهُ أَلْبَسَهُ اللَّهُ ثَوْبَ الذُّلِّ\nکسی که جهاد را ترک کندبا ذلت حقیر میشود.\n\n3️⃣جهاد زبانی (جهاد تبیین):\n✅ وقتی دشمن در حال شبهه پراکنی است واجب فوری و قطعی جهاد تبیین است \n🔺خطبه 51: َ أَلَا وَ إِنَّ مُعَاوِیَهَ قَادَ لُمَهً مِنَ الْغُوَاهِ وَ عَمَّسَ عَلَیْهِمُ الْخَبَرَ حَتَّى جَعَلُوا نُحُورَهُمْ أَغْرَاضَ الْمَنِیَّه\nای مردم آگاه باشید روش معاویه این است که عده ای نادان را دور خودش جمع کرده و از اینها سوء استفاده میکند\nاخبار دروغ دست آنها می‌دهد و آنها این سخنان را میپذیرند. \n✅ پاسخ به شبهات ذهنی مردم توسط حضرت:\nنامه 45: وَ کَأَنِّی بِقَائِلِکُمْ یَقُول‏ ُإِذَا کَانَ هَذَا قُوتُ ابْنِ أَبِی طَالِبٍ فَقَدْ قَعَدَ بِهِ الضَّعْفُ عَنْ قِتَالِ الْأَقْرَانِ وَ مُنَازَلَهِ الشُّجْعَانِ أَلَا وَ إِنَّ الشَّجَرَهَ الْبَرِّیَّهَ أَصْلَبُ عُوداً\nشایعه در سطح جامعه پخش شده که چون علی بن ابی طالب فقط روزی دو قرص نان می‌خورد جانی ندارد تا جهاد کند، حضرت در پاسخ فرمودندکه من همچون درخت بیابانی هستم که کم غذا است ولی محکم. \nحضرت با جهاد تبیین پاسخ شبهه را می‌دهد. \n✅پاسخ به حرفهایی که در بین افراد پخش است:\n🔺 خطبه ۱۷۲: وَ قَدْ قَالَ قَائِلٌ إِنَّکَ عَلَى هَذَا الْأَمْرِ یَا ابْنَ أَبِی طَالِبٍ لَحَرِیصٌ\nدر جریان شوری شش نفره گوینده اى (سعد ابی وقاص) به من گفت:. تو نسبت به این امر ـ یعنى خلافت ـ حریصى!اى فرزند ابوطالب، \n فَقُلْتُ بَلْ أَنْتُمْ وَ اللَّهِ لَأَحْرَصُ  وَ أَبْعَدُ \nدر پاسخش گفتم: به خدا سوگند! شما با این که دورترید، حریص ترید (چرا که خلافت، شایسته اهل بیت پیامبر(علیهم السلام) است که به این کانون هدایت نزدیک ترند)\n وَ أَنَا أَخَصُّ وَ أَقْرَبُ وَ إِنَّمَا طَلَبْتُ حَقّاً لِی وَ أَنْتُمْ تَحُولُونَ بَیْنِی وَ بَیْنَهُ \n(   و من شایسته تر و نزدیکترم. من فقط حق خویش را مطالبه کردم; ولى شما میان من و آن حایل مى شوید و دست ردّ بر سینه ام مى گذارید.\nوَ تَضْرِبُونَ وَجْهِی دُونَهُ فَلَمَّا قَرَّعْتُهُ بِالْحُجَّهِ فِی الْمَلَإِ الْحَاضِرِینَ هَبَّ کَأَنَّهُ بُهِتَ لَا یَدْرِی مَا یُجِیبُنِی \nبِه‏  هنگامى که در آن جمع حاضر با این دلیل کوبنده به او پاسخ گفتم، مبهوت و سرگردان ماند و نمى دانست در پاسخم چه بگوید!. \n✅پاسخ به شخصی که دارد سبک زندگی ریاکارانه را ترویج می‌دهد. \nحکمت 417:\n وَ قَالَ ع لِقَائِلٍ قَالَ بِحَضْرَتِهِ أَسْتَغْفِرُ اللَّهَ ثَکِلَتْکَ أُمُّکَ أَ تَدْرِی مَا الِاسْتِغْفَار…\nحصرت به کسی که از روی ریا مرتب ذکر استغفرالله را میگفت فرمود مادرت به عزایت بنشیند این چه استغفار کردن است…. \n✅امیرالمومنین برای قضاوت و شنیدن حرف مردم مکان خاصی تعیین کرده بود و رو در رو به قضاوت و صحبت با مردم می پرداخت:(ابن ابی الحدید: و کان لأمیر المؤمنین ع بیتٌ سًمّاه بیتُ القِصَص یَلقی الناس فیه رقاعهم) \n🔺نامه 36: عقیل مطالبی را در مدینه شنیده بود در مورد اوضاع به هم ریخته حکومت امیرالمومنین ، حضرت به او نامه می نویسد و اوضاع را تشریح میکند که خبری نیست و من بر اوضاع مسلط هستم.\n🔺حکمت 289:  کَانَ لِی فِیمَا مَضَى أَخٌ فِی اللَّهِ،\nمن در گذشته برادری خدایی داشتم\n وَ کَانَ یُعْظِمُهُ فِی عَیْنِی صِغَرُ الدُّنْیَا فِی عَیْنِهِ، \nآنچه که باعث بزرگ شدن او در چشم من بود کوچک بودن دنیا در چشم او بود. \nوَ کَانَ خَارِجاً مِنْ سُلْطَانِ بَطْنِهِ، فَلَا یَشْتَهِی مَا لَا یَجِدُ وَ لَا یُکْثِرُ إِذَا وَجَدَ، \nشکم پرست نبود اگر برای خوردن چیزی نبود به آن اشتها پیدا نمیکرد و اگر بود زیاده روی نمی‌کرد. \nوَ کَانَ أَکْثَرَ دَهْرِهِ صَامِتاً، فَإِنْ قَالَ بَذَّ الْقَائِلِینَ وَ نَقَعَ غَلِیلَ السَّائِلِینَ\nبیشتر اوقات زندگانى اش ساکت بود و در عین حال اگر سخنى مى گفت بر گویندگان چیره مى شد و عطش سؤال کنندگان را فرو مى نشاند.\n✅راه برون رفت از فتنه ها، جهاد تبیین است:\n🔺درخطبه ۵۰ فرمود: \nإِنَّمَا بَدْءُ وُقُوعِ الْفِتَنِ أَهْوَاءٌ تُتَّبَعُ وَ أَحْکَامٌ تُبْتَدَعُ،\nهمانا آغاز پدید آمدن فتنه ها، هوا پرستى، و بدعت گذارى در احکام آسمانى است،\n یُخَالَفُ فِیهَا کِتَابُ اللَّهِ وَ یَتَوَلَّی عَلَیْهَا رِجَالٌ رِجَالًا عَلَی غَیْرِ دِینِ اللَّهِ. \nنوآورى هایى که قرآن با آن مخالف است، و گروهى «با دو انحراف یاد شده» بر گروه دیگر سلطه و ولایت یابند، که بر خلاف دین خداست.\nفَلَوْ أَنَّ الْبَاطِلَ خَلَصَ مِنْ مِزَاجِ الْحَقِّ لَمْ یَخْفَ عَلَی الْمُرْتَادِینَ، وَ لَوْ أَنَّ الْحَقَّ خَلَصَ مِنْ لَبْسِ الْبَاطِلِ انْقَطَعَتْ عَنْهُ أَلْسُنُ الْمُعَانِدِینَ، \nپس اگر باطل با حق مخلوط نمى شد، بر طالبان حق پوشیده نمى ماند، و اگر حق از باطل جدا و خالص مى گشت زبان دشمنان قطع مى گردید.\nوَ لَکِنْ یُؤْخَذُ مِنْ هَذَا ضِغْثٌ وَ مِنْ هَذَا ضِغْثٌ فَیُمْزَجَانِ، فَهُنَالِکَ یَسْتَوْلِی الشَّیْطَانُ عَلَی أَوْلِیَائِهِ وَ یَنْجُو الَّذِینَ سَبَقَتْ لَهُمْ مِنَ اللَّهِ الْحُسْنی \n امّا قسمتى از حقّ و قسمتى از باطل را مى گیرند و به هم مى آمیزند، آنجاست که شیطان بر دوستان خود چیره مى گردد و تنها آنان که مشمول لطف و رحمت پروردگارند نجات خواهند یافت. \n⏪ چگونه باطل از حق جدا میشود؟ با روشنگری و تبیین\n✅جهاد تبیین با لسان استدلال و بدون فحاشی باشد: \n🔺حکمت ۲۰۶ : أَوَّلُ عِوَضِ اَلْحَلِیمِ مِنْ حِلْمِهِ أَنَّ اَلنَّاسَ أَنْصَارُهُ عَلَى اَلْجَاهِلِ\nو فرمود (ع): نخستین پاداشى که بردبار از بردباریش مى گیرد، این است، که مردم در برابر نادانان حمایتش مى کنند. \n🔺خطبه 206:  و من کلام له علیه السلام و قد سمع قوما من أصحابه یسبون أهل الشام أیام حربهم بصفین‏\nسخنى از آن حضرت (ع) هنگامى که شنید گروهى از اصحابش در جنگ صفین، شامیان را دشنام مى گویند چنین فرمود: \nإِنِّی أَکْرَهُ لَکُمْ أَنْ تَکُونُوا سَبَّابِینَ وَ لَکِنَّکُمْ لَوْ وَصَفْتُمْ أَعْمَالَهُمْ وَ ذَکَرْتُمْ حَالَهُمْ کَانَ أَصْوَبَ فِی الْقَوْلِ…\nدوست ندارم که شما دشنام دهنده باشید. ولى اگر به توصیف اعمال و بیان حالشان بپردازید، سخنتان به صواب نزدیکتر و عذرتان پذیرفته تر است. به جاى آنکه دشنامشان دهید.\nغفرالله لی ولکم","بخش چهارم\nمتن:\nوَ عَلَيْكُمْ بِالتَّوَاصُلِ وَ التَّبَاذُلِ، وَ إِيَّاكُمْ وَ التَّدَابُرَ وَ التَّقَاطُعَ. لَا تَتْرُكُوا الْأَمْرَ بِالْمَعْرُوفِ وَ النَّهْيَ عَنِ الْمُنْكَرِ، فَيُوَلَّى عَلَيْكُمْ [أَشْرَارُكُمْ] شِرَارُكُمْ، ثُمَّ تَدْعُونَ فَلَا يُسْتَجَابُ لَكُمْ.\nثُمَّ قَالَ: يَا بَنِي عَبْدِ الْمُطَّلِبِ، لَا أُلْفِيَنَّكُمْ تَخُوضُونَ دِمَاءَ الْمُسْلِمِينَ خَوْضاً، تَقُولُونَ قُتِلَ أَمِيرُ الْمُؤْمِنِينَ [قُتِلَ أَمِيرُ الْمُؤْمِنِينَ]؛ أَلَا لَا تَقْتُلُنَّ بِي إِلَّا قَاتِلِي، انْظُرُوا إِذَا أَنَا مِتُّ مِنْ ضَرْبَتِهِ هَذِهِ فَاضْرِبُوهُ ضَرْبَةً بِضَرْبَةٍ؛ وَ لَا تُمَثِّلُوا بِالرَّجُلِ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ (صلی الله علیه وآله) يَقُولُ: إِيَّاكُمْ وَ الْمُثْلَةَ وَ لَوْ بِالْكَلْبِ الْعَقُور.\nترجمه:\nو بر شما لازم است پيوندهاى دوستى و محبّت و بذل و بخشش را فراموش نکنيد و بر حذر باشيد از اينکه به يکديگر پشت کنيد و رابطه خود را با هم قطع نماييد. امر به معروف و نهى از منکر را ترک نکنيد که اشرار بر شما مسلّط خواهند شد، سپس هر چه دعا کنيد مستجاب نمى گردد.\nسپس (امام(عليه السلام)) فرمود: اى فرزندان عبدالمطلب! نکند بعد از شهادتم (به بهانه قتل من) در خون مسلمانان فرو رويد و بگوييد: اميرمؤمنان کشته شد. آگاه باشيد جز قاتل من را به سبب قتل من نکشيد. (درست) بنگريد هرگاه من از اين ضربت از دنيا چشم پوشيدم، او را تنها يک ضربت بزنيد تا يک ضربت در برابر يک ضربت باشد. و او را مثله نکنيد (گوش و بينى و اعضاى او را جدا نسازيد) که من از رسول خدا(صلى الله عليه وآله) شنيدم که مى فرمود: «از مثله کردن بپرهيزيد، هرچند نسبت به سگ گزنده باشد!.»\nتفسیر:\n🔵موضوع نامه:وصیت نامه حضرت بعد از ضربت خوردن خطاب به فرزندانشان است و همه کسانی که این نامه به دستشان می‌رسد. \n\n💠 وَ عَلَیْکُمْ بِالتَّوَاصُلِ وَ التَّبَاذُلِ، \nمن شما را امر میکنم به وصل شدن به یکدیگر [تَّوَاصُلِ] وبذل و بخشش نسبت به هم[تَّبَاذُلِ] \n💠وَ إِیَّاکُمْ وَ التَّدَابُرَ وَ التَّقَاطُعَ \nوشما را نهی میکنم از پشت کردن به هم[تَّدَابُرَ] وقطع ارتباط کامل [تَّقَاطُعَ] \nتواصل یعنی اتصال دو طرفی و تباذل یعنی بذل و بخشش دو طرفی، بر همه ما لازم است با هم اتصال داشته باشیم ولی اتصال به معنای  رفت و آمد صرف کافی نیست و باید در آن بذل و بخشش و ایثار نیز لحاظ شود.\n❇️در\nکافی بابی است با نام بَابُ اَلْهِجْرَه \n(هجرت یک معنای  ممدوح دارد و یک معنای مذموم که همان دشمنی و جدایی است)\n🔹هجرت مثبت: \nهجرت مکانی(هجرت مسلمانان از مکه به مدینه برای حفظ دینشان) \n هجرت اعتقادی(هجرت از افکار غلط و خرافه) \nهجرت عملی (هجرت و دوری از کار ناشایستی که قبلا انجام میدادی) \n 🔺پیامبر صلی الله علیه و آله فرمود: \nالْمُهَاجِرُ مَنْ هَجَرَ السَّیِّئَاتِ وَ تَرَکَ مَا حَرَّمَهُ اللَّهُ عَلَیْهِ.\nمهاجر کسی است که از گناهانش هجرت کند و آنچه را که خدا بر او حرام کرده را ترک نماید. \nهجرت منفی: \nقهر، جدایی، قطع رابطه\n🔺سَمِعْتُ أَبَا عَبْدِ اَللَّهِ عَلَیْهِ اَلسَّلاَمُ یَقُولُ:\nاز امام صادق شنیدم که مکرر میفرمود:\n لاَ یَفْتَرِقُ رَجُلاَنِ عَلَى اَلْهِجْرَانِ إِلاَّ اِسْتَوْجَبَ أَحَدُهُمَا اَلْبَرَاءَهَ وَ اَللَّعْنَهَ وَ رُبَّمَا اِسْتَحَقَّ ذَلِکَ کِلاَهُمَا\n دو مرد به طور قهر کردن از هم جدا نشوند جز اینکه یکى از آنها مستحق بیزارى و لعنت است و بسا که هر دو مستحقّ‌ آن باشند\n فَقَالَ لَهُ مُعَتِّبٌ جَعَلَنِیَ اَللَّهُ فِدَاکَ هَذَا اَلظَّالِمُ فَمَا بَالُ اَلْمَظْلُومِ \nمعتب به آن حضرت عرض کرد:خدا مرا قربانت کند،این جزاى ظالم است،مظلوم چه تقصیرى دارد؟\n قَالَ لِأَنَّهُ لاَ یَدْعُو أَخَاهُ إِلَى صِلَتِهِ وَ لاَ یَتَغَامَسُ لَهُ عَنْ کَلاَمِهِ \nفرمود:براى آنکه برادر خود را به پیوست و آشتى با خویش دعوت نمى‌کند و از گفتۀ او صرف نظر مى‌کند. \nسَمِعْتُ أَبِی یَقُولُ إِذَا تَنَازَعَ اِثْنَانِ فَعَازَّ أَحَدُهُمَا اَلْآخَرَ فَلْیَرْجِعِ اَلْمَظْلُومُ إِلَى صَاحِبِهِ حَتَّى یَقُولَ لِصَاحِبِهِ\n شنیدم پدرم مى‌فرمود:هر گاه دو تن با هم ستیزه کردند و یکى بر دیگرى غلبه کرد،آن که ستمدیده نزد طرف ستمگرِ خود رود تا آنکه به او بگوید. \n أَیْ أَخِی أَنَا اَلظَّالِمُ حَتَّى یَقْطَعَ اَلْهِجْرَانَ بَیْنَهُ وَ بَیْنَ صَاحِبِهِ فَإِنَّ اَللَّهَ تَبَارَکَ وَ تَعَالَى حَکَمٌ عَدْلٌ یَأْخُذُ لِلْمَظْلُومِ مِنَ اَلظَّالِمِ\n اى برادر!من به تو ستم کردم ،تا اینکه قهر و متارکه میان او و رفیق او برطرف شود،زیرا خدا حکیم و عادل است ،از ظالم داد مظلوم را مى‌ستاند.\n🔺قَالَ رَسُولُ اللَّهِ ص\nپیامبر صلی الله علیه وآله وسلم فرمودند:\n أَیُّمَا مُسْلِمَیْنِ تَهَاجَرَا فَمَکَثَا ثَلَاثاً لَا یَصْطَلِحَانِ إِلَّا کَانَا خَارِجَیْنِ مِنَ الْإِسْلَامِ \nهرگاه دو مسلمان از هم قهر کنند و سه روز بگذرد و آشتى نکنند اگر در آن حال از دنیا بروند خارج از اسلام خواهند بود\nوَ لَمْ یَکُنْ بَیْنَهُمَا وَلَایَهٌ فَأَیُّهُمَا سَبَقَ إِلَى کَلَامِ أَخِیهِ کَانَ السَّابِقَ إِلَى الْجَنَّهِ- یَوْمَ الْحِسَابِ. \nو ولایت و پیوند اخوت اسلامى در میان آنها قطع مى شود و به هنگام آشتى کردن هر کدام پیشى گیرد او در قیامت براى رفتن به بهشت پیشى خواهد گرفت.\n🔺 امام باقر : \nإنَّ الشَّیطانَ یُغری بَینَ المُؤمِنینَ ما لَم یَرجِع أحَدُهُم عَن دینِهِ \nشیطان ، همچنان به ایجاد دشمنى میان مؤمنان مى پردازد تا آن که یکى از آنان از دین خود بازگردد\nفَإِذا فَعَلوا ذلِکَ استَلقى عَلى قَفاهُ وتَمَدَّدَ\n همین که فریب او اثر کرد به پشت مى افتد و دراز مى کشد \nثُمَّ قالَ : فُزتُ\n سپس مى گوید : «پیروز شدم». \nفَرَحِمَ اللّه ُ اِمرَأً ألَّفَ بَینَ وَلِیَّینِ لَنا \nپس خداوند ، رحمت کند کسى را که میان دو تن از دوستان ما الفت برقرار کند\n یا مَعشَرَ المُؤمِنینَ ، تَأَلَّفوا وتَعاطَفوا \nاى گروه مؤمنان ! با یکدیگر الفت بگیرید و به هم مهربانى کنید. \n💠لَا تَتْرُکُوا الْأَمْرَ بِالْمَعْرُوفِ وَ النَّهْیَ عَنِ الْمُنْکَرِ، \nهمه فرزندان علی و همه بشریت) امر به معروف و نهی از منکر را ترک نکنید، \n💠فَیُوَلَّى عَلَیْکُمْ شِرَارُکُمْ، ثُمَّ تَدْعُونَ فَلَا یُسْتَجَابُ لَکُمْ.\nاگر چنین کردیدانسانهای شرور بر شما مسلط خواهند شد، و پس از آن  دعا میکنید ولی خدا برای شما اجابت نمیکند. \n✅جایگاه امر به معروف و نهی از منکر:\nدر خطبه ۱۵۶ فرمود : \nوَ إِنَّ الْأَمْرَ بِالْمَعْرُوفِ وَ النَّهْیَ عَنِ الْمُنْکَرِ لَخُلُقَانِ مِنْ خُلُقِ اللَّهِ سُبْحَانَهُ وَ إِنَّهُمَا لَا یُقَرِّبَانِ مِنْ أَجَلٍ وَ لَا یَنْقُصَانِ مِنْ رِزْق‏\nامر به معروف و نهی از منکر دو خلق از اخلاق خداوند متعال است، نهی از منکر تاثیری در نزدیکی مرگ یا کم شدن روزی ندارد. \n(مبادا به خاطر ترس از قطع روزی یا کشته شدن، امر به معروف و نهی از منکر ترک شود) \n🔺أَوْحَى اللَّهُ عَزَّ وَ جَلَّ إِلَى شُعَیْبٍ النَّبِیِّ ص أَنِّی مُعَذِّبٌ مِنْ قَوْمِکَ مِائَهَ أَلْفٍ،\nخداوند عزّوجل به شعیب پیامبر وحى فرستاد که من صد هزار نفر از قوم تو را کیفر خواهم داد;\n أَرْبَعِینَ أَلْفاً مِنْ شِرَارِهِمْ وَ سِتِّینَ أَلْفاً مِنْ خِیَارِهِمْ فَقَالَ ع یَا رَبِّ هَؤُلَاءِ الْأَشْرَارُ فَمَا بَالُ الْأَخْیَارِ \nچهل هزار نفر از اشرار و شصت هزار نفر از اخیار! شعیب عرضه داشت: پروردگارا اشرار به جاى خود، اخیار چرا؟\nفَأَوْحَى اللَّهُ عَزَّ وَ جَلَّ إِلَیْهِ دَاهَنُوا أَهْلَ الْمَعَاصِی  وَ لَمْ یَغْضَبُوا لِغَضَبِی \n خداوند عزّوجل به او وحى فرستاد با گنهکاران راه سازش و بى تفاوتى پیش گرفتند و هرگز به جهت خشم من خشمگین نشدند. \n✅لزوم مطابقت گفتار و کردار در امر به معروف :\nخطبه 129: لَعَنَ اللَّهُ الْآمِرِینَ بِالْمَعْرُوفِ التَّارِکِینَ لَهُ \nخدا لعنت کند کسانی که امر به معروف می‌کنند ولی خودشان عمل نمیکنند\nوَ النَّاهِینَ عَنِ الْمُنْکَرِ الْعَامِلِینَ بِه‏\nونهی از منکر می‌کنند ولی خودشان به آن عمل می‌کنند. \n\n✅رابطه بین ترک نهی از منکر و به ریاست رسیدن اشرار\n[فَیُوَلَّى عَلَیْکُمْ شِرَارُکُمْ] :\nوظیفه ی مردم خیرخواهی برای حاکمان و حاکمیت است، \nاگر ما با امر به معروف و نهی از منکر، جلوی کار های ناشایست حاکمان رانگیریم، موجبات غرق شدن حاکمان در منجلاب گناه را فراهم کردیم و در نتیجه حاکمان ما از اشرار خواهند شد. \nخطبه 34:\n أَیُّهَا النَّاسُ إِنَّ لِی عَلَیْکُمْ حَقّاً وَ لَکُمْ عَلَیَّ حَقٌّ……… \nای مردم حقی از شما بر گردن من است و حقی از من بر گردن شما……. \n… وَ النَّصِیحَهُ فِی الْمَشْهَدِ وَ الْمَغِیبِ \n(یکی از حقوق حاکم بر گردن مردم) و در پیش رو و پشت سر من برای من خیرخواه باشید(با نصایح خود مرا امر به معروف و نهی از منکر کنید) \n♦️کافی بابی دارد با نام  «بَابُ مَا أَمَرَ النَّبِیُّ ص بِالنَّصِیحَهِ لِأَئِمَّهِ الْمُسْلِمِینَ» \nباب در رابطه با دستور پیامبر اکرم صلی الله علیه و آله و سلم به نصیحت (انتقاد و پیشنهاد) نسبت به حاکمان مسلمان) :\n🔺پیامبر اکرم: \n ثَلاَثٌ لاَ یُغِلُّ عَلَیْهِنَّ قَلْبُ اِمْرِئٍ مُسْلِمٍ إِخْلاَصُ اَلْعَمَلِ لِلَّهِ وَ اَلنَّصِیحَهُ لِأَئِمَّهِ اَلْمُسْلِمِینَ وَ اَللُّزُومُ لِجَمَاعَتِهِمْ \nسه کار هست که هیچ مسلمانی نباید در آن ناخالصی، خودخواهی و ریا داشته باشد:\n۱.اعمال عبادی \n۲.خیرخواهی برای حاکمان (امر به معروف و نهی از منکر) \n۳. همراه با گروه مسلمانان (اتحاد)\n⏪نتیجه: وقتی مردم بر مبانی دینی حساس نبودند، در مقابل خلاف حاکمیت ایستادگی نکردند، حق را از آنها مطالبه نکردند حاکمیت به سمت بی دینی پیش میرود و بی دین ها (اشرار) حاکم میشوند.\nرابطه بین ترک نهی از منکر و عدم استجابت دعا[ثُمَّ تَدْعُونَ فَلَا یُسْتَجَابُ لَکُمْ.] :\nقرآن کریم میفرماید: إِنَّ اللَّهَ لا یُغَیِّرُ ما بِقَوْمٍ حَتَّی یُغَیِّرُوا ما بِأَنْفُسِهِمْ ؛\n خدای متعال تضمین نداده است که اعمالی که با سوء اختیار ما به وجود می آیند را ختم به خیر و اصلاح کند.\nاگر مردم وظیفه خود در مورد نهی از منکر را انجام ندادند و حاکمانی شرور روی کار آمدند، اینجا دعا مستجاب نمی شود چون “خود کرده را تدبیر نیست”.\n🔺حضرت در خطبه 149 که آن هم وصیت نامه است میفرماید: غَداً تَرَوْنَ أَیَّامِی وَ یُکْشَفُ لَکُمْ عَنْ سَرَائِرِی وَ تَعْرِفُونَنِی بَعْدَ خُلُوِّ مَکَانِی وَ قِیَامِ غَیْرِی مَقَامِی‏ \n وقتی معاویه سر کار آمد تازه به عظمت علی پی میبرید ولی هر چه دعا کنید مستجاب نمی شود چون وظیفه تان را در زمان حضرت انجام ندادید (دفاع از مولا ، مبارزه با معاویه)\n🔺در خطبه 88 فرمود: \nأَمَّا بَعْدُ فَإِنَّ اللَّهَ لَمْ یَقْصِمْ جَبَّارِی دَهْرٍ قَطُّ إِلَّا بَعْدَ تَمْهِیلٍ وَ رَخَاءٍ\nخدا هرگز جبّاران دنیا را در هم نشکسته مگر پس از آن که مهلت هاى لازم و نعمت هاى فراوان بخشید،\n وَ لَمْ یَجْبُرْ عَظْمَ أَحَدٍ مِنَ الْأُمَمِ إِلَّا بَعْدَ أَزْلٍ وَ بَلَاءٍ  \n و هرگز استخوان شکسته ملّتى را باز سازى نفرمود مگر پس از آزمایش ها و تحمّل مشکلات.\n \n اگر امر به معروف و نهی از منکر نکردید و حاکمان ظالم به حکومت رسیدند دیگر دعای شما اثر ندارد و سالها باید زیر شکنجه حاکمان ظالم بسوزید و بسازید.\n\nطبق نقل تمام نهج البلاغه اینجا حضرت فرمودند:\n یَا بَنِیَّ إِنَّ الْقُلُوبَ جُنُودٌ مُجَنَّدَهٌ \nای فرزندانم دلها لشکری آماده اند.\nتَتَلَاحَظُ بِالْمَوَدَّهِ \nکه با چشم دل دوستی را میبینند\nوَ تَتَنَاجَی بِهَا \nو با زبان محبت با یکدیگر صحبت میکنند\nوَ کَذَلِکَ هِیَ فِی الْبُغْضِ \nو البته با چشم دشمنی و زبان دشمنی نیز با عده ای برخورد میکنند\nفَإِذَا أَحْبَبْتُمُ الرَّجُلَ مِنْ غَیْرِ خَیْرٍ سَبَقَ مِنْهُ إِلَیْکُمْ فَارْجُوهُ \nاگر شخصی را دیدید و بدون هیچ شناختی از او، او را دوست داشتید به او امید ببندید\nوَ إِذَا أَبْغَضْتُمُ الرَّجُلَ مِنْ غَیْرِ سُوءٍ سَبَقَ مِنْهُ إِلَیْکُمْ فَاحْذَرُوهُ \nاگر از شخصی بدتان آمد بدون اینکه به شما ضرری رسانده باشد از او دوری کنید. \n⏪نکته: کلام حضرت ناظر به آنجاست که قلب انسان مومن و صاف باشد، قلوب یک زبان و نگاه خاصی دارند که می توانند با پیرامون خود ارتباط بگیرند.\nولی اگر کسی قلب ناپاکی داشت نمی تواند بگوید من از فلان عالم یا عارف بدم آمد پس او شخص بدی است.\n\nادامه وصیتنامه در  نهج البلاغه:  \n💠ثُمَّ قَالَ: یَا بَنِی عَبْدِ الْمُطَّلِبِ، لَا أُلْفِیَنَّکُمْ \nتَخُوضُونَ دِمَاءَ الْمُسْلِمِینَ خَوْضاً \n تَقُولُونَ قُتِلَ أَمِیرُ الْمُؤْمِنِینَ قُتِلَ أَمِیرُ الْمُؤْمِنِینَ؛\nمبادا ببینم شما، با گفتن این شعار احساسی که علی را کشتند، علی را کشتند، در خون مسلمان ها فرو رفته اید. \n🔺علامه شوشتری در بهج الصباغه میفرماید: \nأهل الدنیا إذا قُتِلَ أحدُ کُبرائِهِم \nاهل دنیا گاهی وقتی بزرگی از آنها به قتل می‌رسد به خاطر گشته شدن او  \nیَقتُلُونَ به عدّه القاتل،و غیر القاتل و المحقق،و غیر المحقق\nدست به کشتن عده زیادی از خانواده قاتل می‌کنند چه قاتل باشند چه نباشند چه گناهشان مشخص باشد چه نباشد. \n (تعصبات جاهلی گاهی باعث میشود که افراد پس از انجا قتلی، به جای یک نفر، صد نفر را به قتل میرسانند چه تحقیق شده باشد چه نشده باشد. علامه شوشتری موارد متعددی از این گونه موارد را ذکر کرده است)\n💠أَلَا لَا تَقْتُلُنَّ بِی إِلَّا قَاتِلِی، \nجز قاتلم کسی را نکشید. \n💠انْظُرُوا إِذَا أَنَا مِتُّ مِنْ ضَرْبَتِهِ هَذِهِ فَاضْرِبُوهُ ضَرْبَهً بِضَرْبَهٍ\nنگاه کنید وقتی من با یک ضربه کشته شدم شما هم حق دارید فقط یک ضربه به او بزنی. \n 💠وَ لَا تُمَثِّلُوا بِالرَّجُلِ \nقاتل را مثله نکنید،. \n💠فَإِنِّی سَمِعْتُ رَسُولَ اللَّهِ (صلی الله علیه وآله) یَقُولُ:إِیَّاکُمْ وَ الْمُثْلَهَ وَ لَوْ بِالْکَلْبِ الْعَقُور \nچرا که شنیدم پیامبر اکرم صلی الله علیه و آله و سلم فرمودند:\nاز مثله کردن بپرهیزید حتی اگر سگ هار گزنده باشد .\n✳️نکاتی در مورد دفن امیرالمومنین:\n_حسنین از طرف حضرت مامور شدند با عده ی معدودی شبانه تابوت را به سمت بیرون از کوفه حرکت دهند:\n فلما انتهیا إلى قبره و إذا مقدم السریر قد وضع، \nما دیدیم که جلوی تابوت که دست فرشته ها بود در منطقه ای بر زمین گذاشته شد. \nفوضع الحسن ع مؤخره \nپس امام حسن علیه السلام هم انتهای تابوت را بر زمین گذاشت. \nحضرت خاکها را با دست کنار زد \n و کشفنا التراب و إذا نحن بقبر محفور \nتا اینکه به قبری آماده رسیدیم\nو لحد مشقوق و ساجه منقوره \nکه یک  تخته ی منقوشی در آن بود \nمکتوب علیها هذا ما ادخره له جده نوح النبی للعبد الصالح الطاهر المطهر……. \nروی آن نوشته شده بود این قبری است که نوح برای فرزند خودش آماده کرده\n بعد از اینکه حضرت را دفن می‌کنند صعصعه می‌گوید بعد از خاکسپاری من شروع کردم با قبر امیر المؤمنین صحبت کردن، پدرو مادرم به فدایتان یا امام علی علیه السلام. و گفتم خوش به حال شما ابوالحسن همه عمر با خدا بودی، با شهادت از دنیا رفتی و امشب مهمان رسول الله هستی، بعد برخاستم و به فرزندان امام علی تسلیت گفتم و در همان نیمه شب جمعیت محدود تشییع کننده بازگشتند و قرار بر این شد در این باره با کسی صحبت نشود. \nتا اینکه صبح شد\nأخرجوا تابوتا من دار أمیر المؤمنین ع \nتابوت دیگری از خانه امام خارج شد \nامام حسن بالای تابوت نماز خواندند و تابوت خالی  را آنجا دفن کردند \nوقتی حضرت از کار تدفین فراغت پیدا کردند برای مجازات ابن ملجم دست به کار شدند. \n❎مجازات ابن ملجم مرادی:\nاگر چه نقل های تاریخی متفاوتی در  مورد کیفیت قصاص ابن ملجم وارد است از جمله اینکه بعد از ضربه امام حسن به سر ابن ملجم و مرگ او امام حسین هم ضربه ای به سر او زدند، یا اینکه مردم جسد اورا قطعه قطعه کردند یا او را در گودالی عمیق انداختند و خاک روی او ریختند، یا اینکه از بیم تعرض به جنازه او امام حسن دستور دادند تا اورا بسوزانند که همه اینها به نحوی رد می‌شوند باتوجه به وصیت صریح امام علی علیه السلام بعید است امام حسن اجازه چنین کارهایی داده باشند\nوبه نظر می رسد این نقل‌هابیشتر به جهت شبهه افکنی و تخریب ائمه صادر شده است.\nعلت مخفی بودن قبر امیرالمومنین (امیرالمومنین هم شبانه تشییع شد و قبرش بی نشان بود):\n1️⃣وصیت خود حضرت :\nشیخ مفید در الارشاد:  وَ عَفَیَا مَوْضِعَ قَبْرِهِ بِوَصِیَّهٍ کَانَتْ مِنْهُ إِلَیْهِمَا فِی ذَلِکَ\nبه وصیت خود حضرت محل قبر را مخفی کردن\n  لِمَا کَانَ یَعْلَمُهُ ع مِنْ دَوْلَهِ بَنِی أُمَیَّهَ مِنْ بَعْدِهِ\nبه خاطر دشمنی دولت بنی امیه با آن حضرت و این که امام حسن علیه السلام میدانستند اگر قبر حضرت مشخص باشد ممکن است از سوی حکومت بنی امیه جسارتی به قبر حضرت بشود. \n\n2️⃣تصمیم حسنین:\nابن ابی الحدید:  أن علیا ع لما قتل قصد بنوه أن یخفوا قبره خوفا من بنی أمیه أن یحدثوا فی قبره حدثا\nابن ابی الحدید علت مخفی شدن قبر حضرت را ترس فرزندان حضرت از بی حرمتی به قبر حضرت توسط بنی امیه اعلام کردند \n3️⃣ترس از نبش قبر توسط خوارج: \nالغارات: و کان السّبب فی …\n إخفاء قبره خوفا من الخوارج و المنافقین، و کان لا یعرف ذلک إلّا خاصّ الخاصّ من الشّیعه\nدر کتاب غارات علاوه بر خطر حکومت معاویه خطر منافقین و خوارج را هم بیان می‌کند. \n4️⃣ابن کثیر در البدایه و النهایه: \nأَنَّ عَلِیًّا رَضِیَ اللَّهُ عَنْهُ لَمَّا مَاتَ صَلَّى عَلَیْهِ ابْنُهُ الْحَسَنُ فَکَبَّرَ عَلَیْهِ تِسْعَ تَکْبِیرَاتٍ وَدُفِنَ بِدَارِ الْإِمَارَهِ بِالْکُوفَهِ خَوْفًا عَلَیْهِ مِنَ الْخَوَارِجِ أَنْ یَنْبُشُوا عَنْ جُثَّتِهِ \nایشان دفن حضرت را بر خلاف روایت صریحی که به ما رسیده در کوفه  میدانند ولی علت را ترس از نبش قبر توسط خوارج می‌دانند. \n✅زیارت غریبانه امیرالمومنین توسط ائمه:\nامام باقر میفرماید پدرم امام سجاد بعد از شهادت اباعبد الله تا مدتی داخل شهر نمی شد و بیرون از مدینه چادر زده بود و گاهی به سمت عراق می آمد برای زیارت امام حسین و امیرالمومنین. امام باقر میفرماید: فَخَرَجَ سَلَامُ اللَّهِ عَلَیْهِ مُتَوَجِّهاً إِلَى الْعِرَاقِ لِزِیَارَهِ أَمِیرِ الْمُؤْمِنِینَ ع\nامام سجاد علیه السلام برای زیارت امیرالمومنین از مدینه به سمت عراق  رفتند \n وَ أَنَا مَعَهُ وَ لَیْسَ مَعَنَا ذُو رُوحٍ إِلَّا النَّاقَتَیْنِ \nومن هم همراه حضرت رفتم و کنار ماجز دو مرکبمان هیچ موجود زنده ای نبود. \nفَلَمَّا انْتَهَى إِلَى النَّجَفِ مِنْ بِلَادِ الْکُوفَهِ وَ صَارَ إِلَى مَکَانِهِ مِنْهُ فَبَکَا حَتَّى اخْضَلَّتْ لِحْیَتُهُ بِدُمُوعِهِ\nحضرت وقتی به نجف رسیدند به سمت مکانی از آنجا (که قبر امیرالمومنین در آن مخفی بوده) نزدیک شدند و به شدت می‌گریستند. \n ثُمَّ قَالَ\nسپس فرمودند: \nالسَّلَامُ عَلَیْکَ یَا أَمِیرَ الْمُؤْمِنِینَ وَ رَحْمَهُ اللَّهِ وَ بَرَکَاتُه‏. \n\nغفر اللّه لی و لکم الحمدللّه رب العالمین"]});
